package com.visionerp.controller; import com.visionerp.entity.Department; import com.visionerp.repository.DepartmentRepository; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/departments") public class DepartmentController {private final DepartmentRepository r;public DepartmentController(DepartmentRepository r){this.r=r;}@GetMapping public List<Department> all(){return r.findAll();}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','HR')")public Department create(@RequestBody Department d){d.id=null;return r.save(d);}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','HR')") public Department update(@PathVariable Long id,@RequestBody Department d){Department x=r.findById(id).orElseThrow();x.name=d.name;x.description=d.description;return r.save(x);}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")public void delete(@PathVariable Long id){r.deleteById(id);}}
